//! Closed printed MSJC16. Seven grave cards are paid before the response window.
use crate::{catalog,engine::RuleResult,model::*,rules::*,society::{SocietyDefinition,SocietyDeckConstraint}};
use serde::{Serialize,Deserialize};
use std::collections::BTreeSet;
pub(crate) const ID:&str="MSJC16";
pub(crate) const INITIAL:&str="msjc16-first-preparation";
pub(crate) const MILL:&str="msjc16-mill";
pub(crate) const REVIVE:&str="msjc16-revive";
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn targets()->Vec<TargetSlotSpec>{let mut grave=target(Zone::Graveyard,EntityKind::Character,Relation::Any,Range::Anywhere);grave.predicate=Some(TargetPredicate::MSJC16Death);vec![grave,target(Zone::Region,EntityKind::Any,Relation::Any,Range::Anywhere)]}
pub(crate) fn definition()->Definition{
 let initial=ability(INITIAL,"首回合准备：将牌库顶三张牌置墓",Timing::Fast,vec![],vec![],vec![Op::MSJC16Prepare{event_id:None}],Some(Event::Prepare));
 let mut mill=ability(MILL,"支付3并横置：牌库顶一张置墓",Timing::Standard,vec![Cost::Assets(3),Cost::ExhaustSource],vec![],vec![Op::MSJC16Mill],None);mill.activation_only=true;
 let mut revive=ability(REVIVE,"支付6、横置并封印墓地七张牌：死亡角色进入目标地区",Timing::Standard,vec![Cost::Assets(6),Cost::ExhaustSource,Cost::MSJC16SealSeven],targets(),vec![Op::MSJC16Revive],None);revive.activation_only=true;with_abilities(vec![initial,mill,revive])
}
pub(crate) fn society()->SocietyDefinition{let mut card:catalog::CardDefinition=serde_json::from_value(serde_json::json!({"id":ID,"name":"颂亡者","kind":"society","type":"秘社/法师结社/分支","subtypes":["法师结社","分支"],"color":"黑","society":"方碑序列","unique":true,"supported":false,"text":"构筑仅黑、中立或死亡领域牌。第一个回合准备开始触发：牌库顶三张置墓。行动3、横置：牌库顶一张置墓。行动6、横置、将自己墓地七张牌封印在颂亡者上：墓地目标死亡领域角色正面进入目标地区。"})).unwrap();card.abilities=definition().abilities.iter().map(|a|catalog::AbilitySummary{key:a.key.clone(),label:a.label.clone(),timing:if a.event.is_some(){"fast"}else{"standard"}.into(),costs:a.costs.clone(),triggered:a.event.is_some()}).collect();SocietyDefinition{card,subtitle:"葬仪主祭".into(),printed_cost:None,starting_hand:5,deck_constraints:vec![SocietyDeckConstraint::BlackNeutralOrDeath],unresolved_abilities:Default::default()}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("msjc16-")||a.costs.iter().any(|c|matches!(c,Cost::MSJC16SealSeven))||a.ops.iter().any(|o|matches!(o,Op::MSJC16Prepare{..}|Op::MSJC16Mill|Op::MSJC16Revive))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id==ID&&a.key==INITIAL{if !matches!(a.ops.as_slice(),[Op::MSJC16Prepare{..}]){return Err("首回合准备不能替换程序".into());}return crate::jc035::validate_ability(id,a);}if id!=ID||!definition().abilities.iter().skip(1).any(|b|same(a,b)){return Err("颂亡者须保留完整印刷费用、目标及程序".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if (id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("颂亡者定义不能删改或移植".into());}Ok(())}
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PaymentDraft{pub actor:usize,pub turn:u32,pub source:SourceSnapshot,pub action:Action,pub targets:Vec<BoundTarget>}
impl Game{
 pub(crate) fn msjc16_action(&self,actor:usize,a:&Action)->RuleResult<()>{if a.kind!="activate"||!self.players[actor].society_zone.card.as_ref().is_some_and(|c|c.definition==ID&&a.card_id.as_deref()==Some(&c.id)){return Ok(());}let key=a.ability_id.as_deref().ok_or("须指定颂亡者行动")?;if !matches!(key,MILL|REVIVE)||*a!=(Action{card_id:a.card_id.clone(),ability_id:a.ability_id.clone(),target_id:if key==REVIVE{a.target_id.clone()}else{None},region:if key==REVIVE{a.region}else{None},cost_selected:if key==REVIVE{a.cost_selected.clone()}else{None},..Action::new("activate")}){return Err("颂亡者只声明原能力、原双目标及七封费用".into());}Ok(())}
 fn msjc16_source(&self,actor:usize,s:&SourceSnapshot)->RuleResult<()>{let c=&s.card;if actor>=self.players.len()||c.definition!=ID||c.owner!=actor||c.controller!=actor||c.face_down||c.exhausted||!self.mystic_instance_valid(&c.id)||s.region.is_some()||s.source_region_instance.is_some()||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some(){return Err("颂亡者原明置未横置秘社来源损坏".into());}self.mobility_immutable_identity(c)}
 fn msjc16_options(&self,actor:usize,source:&Card)->Vec<ChoiceOption>{self.bq095_reference_cards(source).iter().map(|c|self.option(c,actor,None,None)).collect()}
 fn msjc16_draft(&self,d:&PaymentDraft)->RuleResult<()>{self.msjc16_source(d.actor,&d.source)?;self.msjc16_action(d.actor,&d.action)?;if self.turn!=d.turn||d.action.ability_id.as_deref()!=Some(REVIVE)||d.action.cost_selected.is_some()||self.players[d.actor].society_zone.card.as_ref()!=Some(&d.source.card)||self.bq095_reference_cards(&d.source.card).len()<7{return Err("七封未付款声明失去原来源或实际可选墓地".into());}let a=definition().abilities.remove(2);if self.status!="playing"||self.players[d.actor].eliminated||self.window!=Some(Window::Action(self.team(d.actor)))||self.priority_team!=self.team(d.actor)||!self.stack.is_empty(){return Err("七封须保留原标准行动权".into());}if !same(&self.bind_action(d.actor,&d.source,&a,&d.action)?,&d.targets){return Err("七封原目标已改变".into());}let mut probe=self.clone();probe.pay(d.actor,6)?;Ok(())}
 pub(crate) fn msjc16_begin_payment(&mut self,actor:usize,source:SourceSnapshot,action:Action,targets:Vec<BoundTarget>)->RuleResult<()>{let draft=PaymentDraft{actor,turn:self.turn,source,action,targets};self.msjc16_draft(&draft)?;let options=self.msjc16_options(actor,&draft.source.card);self.choice(actor,"msjc16-seven","选择七张本人墓地牌作为封印费用".into(),options,7,7,None,ChoiceResolution::MSJC16Payment{draft:Box::new(draft)});Ok(())}
 pub(crate) fn msjc16_finish_payment(&mut self,d:PaymentDraft,a:&Action,ids:&[String])->RuleResult<()>{self.msjc16_draft(&d)?;if *a!=(Action{choice_id:a.choice_id.clone(),selected:a.selected.clone(),..Action::new("choose")}){return Err("七封选择不能夹带新目标".into());}let mut action=d.action;action.cost_selected=Some(ids.to_vec());self.apply_inner(d.actor,action)}
 pub(crate) fn msjc16_pay(&mut self,actor:usize,s:&SourceSnapshot,a:&Action)->RuleResult<PaidCost>{self.msjc16_source(actor,s)?;let ids=a.cost_selected.as_ref().ok_or("须先选择七封费用")?;if ids.len()!=7||ids.iter().collect::<BTreeSet<_>>().len()!=7{return Err("须选择恰好七张不同墓地牌".into());}let mut paid=vec![];for id in ids{paid.push(self.bq095_reference_cards(&s.card).iter().find(|c|c.id==*id).cloned().ok_or("费用不在本人墓地")?);}for id in ids{let c=self.bq095_take_reference(&s.card,id)?;self.seal_card_on_valid_host(c,actor,&format!("society:p{actor}"));}Ok(PaidCost::MSJC16Sealed(paid))}
 pub(crate) fn msjc16_frame(&self,f:&ResolutionFrame)->RuleResult<()>{let ours=f.source.card.definition==ID||f.ability_key.starts_with("msjc16-")||f.already_paid.iter().any(|p|matches!(p,PaidCost::MSJC16Sealed(_)))||f.steps.iter().any(|s|matches!(s.op,Op::MSJC16Mill|Op::MSJC16Revive|Op::MSJC16Prepare{..}));if !ours{return Ok(());}if f.ability_key==INITIAL{if f.source.card.definition!=ID||!matches!(f.steps.as_slice(),[Step{op:Op::MSJC16Prepare{..},..}]){return Err("首回合准备来源和程序不符".into());}return self.validate_jc035_frame(f);}self.msjc16_source(f.actor,&f.source)?;self.validate_resource_frame(f)?;let spec=definition().abilities.into_iter().find(|a|a.key==f.ability_key).ok_or("未知颂亡者程序")?;let revive=f.ability_key==REVIVE;
  if !self.mystic_instance_number(&f.source.card.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||!same(&f.steps,&spec.ops.iter().map(|o|Step{context:f.actor,op:o.clone()}).collect())||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||f.already_paid.len()!=if revive{3}else{2}{return Err("颂亡者原费用或执行边界损坏".into());}
  let(PaidCost::Assets(ids),PaidCost::Exhausted(id))=(&f.already_paid[0],&f.already_paid[1])else{return Err("颂亡者缺原货币与横置回执".into());};if id!=&f.source.card.id||f.money_units(0)!=if revive{6}else{3}||ids.iter().collect::<BTreeSet<_>>().len()!=ids.len()||ids.iter().any(|id|!self.mystic_instance_valid(id)){return Err("颂亡者支付数额不符".into());}
  if revive{let PaidCost::MSJC16Sealed(cards)=&f.already_paid[2]else{return Err("缺七封支付回执".into());};if cards.len()!=7||cards.iter().map(|c|&c.id).collect::<BTreeSet<_>>().len()!=7{return Err("原七封不能增减或重复".into());}for c in cards{if c.face_down||c.controller!=f.actor||c.owner!=f.actor||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b){return Err("七封支付原墓地身份损坏".into());}self.mobility_immutable_identity(c)?;}if f.targets.len()!=2||f.chosen_region.is_none(){return Err("复归须保留两个原目标".into());}for(t,spec)in f.targets.iter().zip(targets()){if !same(&t.spec,&spec)||t.public.instance_id!=t.id||!t.public.valid||t.public.status!="valid"||t.public.invalid_reason.is_some(){return Err("复归目标合同损坏".into());}}if f.targets[1].id!=format!("region:{}",f.chosen_region.unwrap())||f.targets[1].region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||!self.mystic_instance_valid(&f.targets[0].id){return Err("复归须冻结实际地区与墓地实例".into());}}
  else if !f.targets.is_empty()||f.chosen_region.is_some(){return Err("置墓一张没有目标".into());}Ok(())
 }
 pub(crate) fn msjc16_resolve(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.msjc16_frame(f)?;if f.cursor!=1{return Err("须消费颂亡者原步骤".into());}if f.ability_key==MILL{return self.mill_cards_with_cause(f.actor,1,Some(f));}if f.ability_key!=REVIVE{return Err("未知颂亡者结算".into());}if !f.targets.iter().all(|t|self.valid_bound_target(f.actor,&f.source,t)){return Ok(());}self.own_graveyard_entry(&f.source.card,f.actor,f.chosen_region.unwrap(),&f.targets[0].id)?;Ok(())}
 pub(crate) fn validate_msjc16_state(&self)->RuleResult<()>{let mut seen=BTreeSet::new();for i in &self.stack{if let Some(f)=&i.frame{self.msjc16_frame(f)?;if f.source.card.definition==ID&&f.ability_key!=INITIAL{if !seen.insert(f.frame_id.clone())||i.card.is_some()||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||i.target.as_deref()!=f.targets.first().map(|t|t.id.as_str())||f.cursor!=0{return Err("颂亡者响应外壳损坏或重复".into());}}}}for e in &self.effects{match e{Effect::Frame{frame:f}=>{self.msjc16_frame(f)?;if f.source.card.definition==ID&&f.ability_key!=INITIAL{return Err("颂亡者单步不应留下重复续体".into());}},Effect::Declare{declaration:d}if d.source.card.definition==ID||related(&d.ability)=>{if d.ability.key!=INITIAL{return Err("普通行动不可伪装触发".into());}validate_ability(&d.source.card.definition,&d.ability)?;},_=>{}}}
  if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Declare{declaration:d,..}if d.source.card.definition==ID||related(&d.ability)=>{if d.ability.key!=INITIAL{return Err("颂亡者普通行动不能伪装可选触发".into());}validate_ability(&d.source.card.definition,&d.ability)?;},ChoiceResolution::MSJC16Payment{draft:d}=>{self.msjc16_draft(d)?;let expected=Choice{id:p.choice.id.clone(),kind:"msjc16-seven".into(),title:"选择七张本人墓地牌作为封印费用".into(),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(d.actor),options:self.msjc16_options(d.actor,&d.source.card),min:Some(7),max:Some(7),amount:None,allow_decline:Some(false),preview_cards:vec![]};if p.seat!=d.actor||!self.mystic_instance_valid(&p.choice.id)||!same(&expected,&p.choice){return Err("七封待选合同损坏".into());}},ChoiceResolution::Frame{frame:f,..}=>{self.msjc16_frame(f)?;if f.source.card.definition==ID{return Err("颂亡者付费后无额外选择".into());}},_=>{}}}Ok(())}
}
